%   returns taus: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hs = 0;
    taus = 0;
    h__140 = 3;
    if h__140 < 0, h__140 = NaN; else, h__140 = sqrt(h__140); end
    r = h__140;
    hs = (r * h);
    taus = (r * tau);
end
